"""T-027: the datapack part of the Cemetery of the Fallen Knights and the Keeper's Lodge, written by tools/build/r1_cemetery.py:
function/cemetery/gen/*, structure/cemetery/*.nbt, loot_table/cemetery/*, item_modifier/cemetery/*, dialog/cemetery/*. Generated, do not
edit. The hand-written logic: function/cemetery/*.mcfunction.

Scores (objective le.cem): #q the quest (0 not taken, 1 taken, 2 key found, 3 door open, 4 Magister laid to rest), #g<n> grave n (0 closed,
1 opened), #dist the unrest of the cemetery, #dlast gametime of the last opening, #bellcd gametime the bell works again, #door (0/1),
#ks the key (0 in Thane's coffin, 1 carried, 2 used in the door), #sh the shovel (0 never given, 1 given, 2 lost), #ss the seal (0 not yet,
1 in the sarcophagus, 2 carried), #mg the Magister (0 asleep, 3 rising, 1 fighting, 2 laid to rest), #mt his timer, #ml the leash timer,
#mh the half (0/1), #faded (0/1, the R1 fading) and #fv (what the world shows). Mirrored in storage last_ember:cemetery.
Players: le.ctrig (trigger: 1 take the shovel, 2 the absolution, 9 the swords), le.cbell (the bell rung, vanilla statistic), le.cspy
(gametime the souls are seen till), le.cspc (the spyglass again at), le.chp (health). Spirits: le.cst (their timer)."""
import json, os, subprocess

def tx(t, color="white", italic=False): return {"text": t, "color": color, "italic": italic}
KEEPER = "Смотритель"
DLG = {
    "intro": "Опять живые. Ночью туда не ходите. Хотя всё равно пойдёте. Я сорок лет хороню рыцарей у Брода. Все лежат. Кроме одного. Магистр Ордена Ясеня встаёт каждую ночь и ходит по своему склепу. Ключ от склепа он велел зарыть с оруженосцем, чтобы никто не тревожил. Вот и не тревожат. Возьмите лопату. Найдите Тейна. Упокойте старика.",
    "wait": "Тейн лежит с честью, как все, кто не отступил. Читайте камни. Книга учёта наверху. И копайте с умом: не тех будить — себе дороже.",
    "key": "Ключ у вас. Магистр в нижнем зале. Бейте, пока не ляжет. Он поймёт.",
    "done": "Лёг. Сорок лет… Печать его теперь ваша. Колоссы у замка помнят его руку и пропустят. А если земля дала вам чужое железо — несите сюда. Отпою.",
    "faded": "Огонь ушёл дальше. А я остался с ними. Кто-то же должен.",
    "swords": "Мечи в земле — могилы тех, кто нёс огонь до вас. Три — на холме у меня под окном. Один — у воды под лестницей замка. Один — в черепе каменного змея, на севере, за Вереском. И маленький — у дороги к Плачущим, где тополь пророс сквозь гарду.",
}
CURSES = {1: ("blood", "Кровь"), 2: ("weight", "Тяжесть"), 3: ("dark", "Тьма"), 4: ("hunger", "Голод"), 5: ("weak", "Слабость")}
GRAVE_ITEMS = {   # grave: (item, name, enchantments, durability left)
    1: ("minecraft:iron_sword", "Меч Сира Кадана", {"minecraft:sharpness": 2}, 0.25),
    2: ("minecraft:chainmail_chestplate", "Кольчуга Ворот", {"minecraft:protection": 2}, 0.30),
    3: ("minecraft:iron_helmet", "Шлем Брата Геста", {"minecraft:protection": 1, "minecraft:thorns": 1}, 0.25),
    4: ("minecraft:iron_leggings", "Поножи Ивора", {"minecraft:protection": 2}, 0.30),
    5: ("minecraft:iron_boots", "Сапоги Сиры Лейн", {"minecraft:feather_falling": 1, "minecraft:protection": 1}, 0.35),
}
ITEMS = {
    "cem_shovel": 'minecraft:iron_shovel[minecraft:unbreakable={},minecraft:can_break={blocks:"minecraft:soul_soil"},minecraft:custom_data={le_citem:"cem_shovel",le_keep:1b,gen:$(gen)},'
                  'minecraft:item_name={"text":"Лопата смотрителя","color":"gold","italic":false},minecraft:lore=[{"text":"Берёт только могильную землю.","color":"gray","italic":false}]]',
    "crypt_key": 'minecraft:stick[minecraft:item_model="last_ember:cemetery/crypt_key",minecraft:custom_data={le_citem:"crypt_key",le_keep:1b,gen:$(gen)},minecraft:max_stack_size=1,'
                 'minecraft:item_name={"text":"Ключ склепа","color":"gold","italic":false},minecraft:lore=[{"text":"Холодный. Пахнет землёй.","color":"gray","italic":false}]]',
    "seal": 'minecraft:stick[minecraft:item_model="last_ember:cemetery/seal",minecraft:custom_data={le_citem:"seal",le_keep:1b,gen:$(gen)},minecraft:max_stack_size=1,'
            'minecraft:item_name={"text":"Печать Магистра","color":"gold","italic":false},minecraft:lore=[{"text":"Колоссы помнят эту руку.","color":"gray","italic":false}]]',
}
LEATHER = 11393254           # the pale blue of the knight spirits

def run(R, meta, out):
    ROOT, DP = R.ROOT, R.DP
    GEN = os.path.join(DP, "function/cemetery/gen"); os.makedirs(GEN, exist_ok=True)
    for f in os.listdir(GEN):
        if f.endswith(".mcfunction"): os.remove(os.path.join(GEN, f))
    hdr = "# generated by tools/build/r1_cemetery.py (cemetery_dp.py): "
    def w(name, lines): open(os.path.join(GEN, name + ".mcfunction"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
    W = meta["W"]; gv = meta["graves"]; cr = meta["crypt"]; lo = meta["lodge"]
    cx1, cz1, cx2, cz2 = R.P.CEM
    CBOX = "x=%d,y=%d,z=%d,dx=%d,dy=%d,dz=%d" % (cx1, W - 32, cz1, cx2 - cx1, 160, cz2 - cz1)
    NEAR = "x=%d,y=%d,z=%d,dx=%d,dy=%d,dz=%d" % (cx1 - 32, W - 60, cz1 - 32, cx2 - cx1 + 64, 240, cz2 - cz1 + 64)
    hx1, hy1, hz1, hx2, hy2, hz2 = cr["hall"]
    HALL = "x=%d,y=%d,z=%d,dx=%d,dy=%d,dz=%d" % (hx1, hy1, hz1, hx2 - hx1, hy2 - hy1 + 1, hz2 - hz1)
    sx, sy, sz = cr["sarc"]
    LOAD = "if loaded %d 0 %d if loaded %d 0 %d if loaded %d 0 %d if loaded %d 0 %d" % (cx1, cz1, cx2, cz2, cx1, cz2, cx2, cz1)
    # ------------------------------------------------------------------ init / state
    keys = ["q", "dist", "dlast", "bellcd", "door", "ks", "sh", "ss", "mg", "faded", "fv"] + ["g%d" % g["n"] for g in gv]
    L = [hdr + "the scores from the storage (a reload keeps them; lost scores come back from the storage); a new world: fresh"]
    L.append("execute unless data storage last_ember:cemetery q run function last_ember:cemetery/gen/fresh")
    for k in keys: L.append("execute store result score #%s le.cem run data get storage last_ember:cemetery %s" % (k, k))
    for k in ("mt", "ml", "mh"): L.append("scoreboard players set #%s le.cem 0" % k)
    L.append("execute if score #mg le.cem matches 1 run scoreboard players set #mg le.cem 0")
    L.append("execute if score #mg le.cem matches 3 run scoreboard players set #mg le.cem 0")
    w("init", L)
    w("fresh", [hdr + "a new world"] + ["data modify storage last_ember:cemetery %s set value 0" % k for k in keys] +
      ["data modify storage last_ember:cemetery gen set value {cem_shovel:1,crypt_key:1,seal:1}"])
    w("save", [hdr + "the scores into the storage"] + ["execute store result storage last_ember:cemetery %s int 1 run scoreboard players get #%s le.cem" % (k, k) for k in keys])
    # ------------------------------------------------------------------ the quest items
    for key, stack in ITEMS.items():
        w("give_" + key, [hdr + "give the quest item %s to @s (macro: gen)" % key, "$give @s %s 1" % stack])
        w("item_" + key, [hdr + "the quest item %s as an item entity here (never despawns), macro: gen" % key,
                          "$summon minecraft:item ~ ~ ~ {Age:-32768s,PickupDelay:10s,Motion:[0.0d,0.1d,0.0d],Item:{id:\"%s\",count:1,components:%s}}" % (stack.split("[")[0], comp_json(stack))])
    # ------------------------------------------------------------------ the graves
    L = [hdr + "every second (the cemetery loaded): a coffin lid opened for the first time -> its content, the unrest, a wave of spirits"]
    for g in gv:
        if g["kind"] == "pit": continue
        n = g["n"]; lx, ly, lz = g["lid"]
        L.append("execute if score #g%d le.cem matches 0 if block %d %d %d minecraft:dark_oak_trapdoor[open=true] run function last_ember:cemetery/gen/open_%d" % (n, lx, ly, lz, n))
        L.append("execute if score #g%d le.cem matches 0 if block %d %d %d minecraft:dark_oak_trapdoor[open=true] run function last_ember:cemetery/gen/open_%d" % (n, lx, ly, lz + 1, n))
        ox, oy, oz = g["coffin"]
        add = {"right": 1, "thane": 1, "wrong": 3}[g["kind"]]
        O = ["# grave %d (%s): first opening" % (n, g["kind"]), "scoreboard players set #g%d le.cem 1" % n,
             "execute store result score #dlast le.cem run time query gametime", "scoreboard players add #dist le.cem %d" % add]
        if g["kind"] == "right":
            O.append("loot spawn %d.5 %d.2 %d.5 loot last_ember:cemetery/grave_%d" % (ox, oy, oz, n))
        elif g["kind"] == "wrong":
            O.append("loot spawn %d.5 %d.2 %d.5 loot last_ember:cemetery/bones" % (ox, oy, oz))
        O.append("execute positioned %d.5 %d %d.5 as @e[type=minecraft:item,distance=..2] run data merge entity @s {Age:-32768s}" % (ox, oy, oz))
        O.append("playsound minecraft:block.wooden_trapdoor.open block @a[distance=..16] %d %d %d 1 0.6" % (lx, ly, lz))
        O.append("function last_ember:cemetery/save")
        O.append("function last_ember:cemetery/wave {x:%d,y:%d,z:%d}" % (g["x"], g["y"] + 1, g["z"]))
        w("open_%d" % n, O)
    w("graves", L)
    w("pits_clean", [hdr + "every second: the soul soil the collapse of a sunken grave dropped onto its bottom goes (the pit stays 4 deep, soul soil only in the graves)"] +
      ["fill %d %d %d %d %d %d minecraft:air replace minecraft:soul_soil" % (g["x"], g["y"] - 3, g["z"], g["x"], g["y"] - 1, g["z"] + 1) for g in gv if g["kind"] == "pit"])
    th = next(g for g in gv if g["kind"] == "thane")
    tx_, ty_, tz_ = th["coffin"]; lx, ly, lz = th["lid"]
    w("key", [hdr + "every second: the crypt key of Thane's coffin (0 in the coffin: it is put there when the lid is open; 1 carried; 2 in the door)",
              "execute if score #ks le.cem matches 0 run function last_ember:cemetery/key_check",
              "execute if score #ks le.cem matches 0 if block %d %d %d minecraft:dark_oak_trapdoor[open=true] positioned %d.5 %d.3 %d.5 unless entity @e[type=minecraft:item,distance=..2] run function last_ember:cemetery/key_put" % (lx, ly, lz, tx_, ty_, tz_),
              "execute if score #ks le.cem matches 0 if block %d %d %d minecraft:dark_oak_trapdoor[open=true] positioned %d.5 %d.3 %d.5 unless entity @e[type=minecraft:item,distance=..2] run function last_ember:cemetery/key_put" % (lx, ly, lz + 1, tx_, ty_, tz_),
              "execute if score #ks le.cem matches 1 run function last_ember:cemetery/key_carried"])
    w("key_at", [hdr + "the key into Thane's coffin (the current generation)", "data modify storage last_ember:cemetery tmp set value {gen:1}",
                 "data modify storage last_ember:cemetery tmp.gen set from storage last_ember:cemetery gen.crypt_key",
                 "execute positioned %d.5 %d.3 %d.5 run function last_ember:cemetery/gen/item_crypt_key with storage last_ember:cemetery tmp" % (tx_, ty_, tz_)])
    w("lid_close", [hdr + "Thane's coffin closed again (the key went back into it)"] +
      ["setblock %d %d %d minecraft:dark_oak_trapdoor[facing=north,half=top,open=false,powered=false,waterlogged=false]" % (lx, ly, lz + d) for d in (0, 1)])
    w("key_near_coffin", [hdr + "#c = items lying in Thane's coffin", "execute store result score #c le.cem positioned %d.5 %d.3 %d.5 if entity @e[type=minecraft:item,distance=..2.5]" % (tx_, ty_, tz_)])
    # ------------------------------------------------------------------ waves: the points the spirits may stand on are found at run time (macro)
    # ------------------------------------------------------------------ the keeper, the dog, the click boxes (spyglass, door, seal)
    ch, hh = lo["chair"], lo["hearth"]; dg = lo["dog"]; sp = lo["spyglass"]; dr = cr["door"]
    KP = {"day": (ch[0] + 0.5, ch[1] + 0.5, ch[2] + 0.5, -90.0), "night": (hh[0] + 0.5, hh[1], hh[2] + 0.5, 180.0),
          "faded": (dr[0] + 2.5, dr[1], dr[2] + 2.5, 180.0)}
    DG = {"home": (dg[0] + 0.5, dg[1], dg[2] + 0.5, 180.0), "faded": (dr[0] - 1.5, dr[1], dr[2] + 2.5, 160.0)}
    L = [hdr + "every second: the keeper (where he should be: day in the armchair, night by the hearth, after the fading at the crypt door;",
         "# he goes over only when no player is within 12 of him), his dog, the click boxes"]
    for k, (x, y, z, yaw) in KP.items():
        sel = {"day": "#kp le.cem matches 0", "night": "#kp le.cem matches 1", "faded": "#kp le.cem matches 2"}[k]
        w("keeper_%s" % k, [hdr + "the keeper to his place: %s" % k, "kill @e[type=minecraft:villager,tag=le.ckeeper]", "kill @e[type=minecraft:interaction,tag=le.ckeep]",
                            'summon minecraft:villager %.1f %.1f %.1f {NoAI:1b,Invulnerable:1b,PersistenceRequired:1b,Silent:1b,CanPickUpLoot:0b,Rotation:[%.1ff,0f],CustomName:{text:"%s",color:"gray"},CustomNameVisible:1b,Tags:["le.npc","le.keep","le.noelite","le.ckeeper"],VillagerData:{profession:"minecraft:nitwit",level:1,type:"minecraft:taiga"},Offers:{Recipes:[]}}' % (x, y, z, yaw, KEEPER),
                            'summon minecraft:interaction %.1f %.1f %.1f {Tags:["le.ckeep"],width:0.9f,height:2.1f,response:1b}' % (x, y, z)])
        L.append("execute if score %s if loaded %d %d %d unless entity @e[type=minecraft:villager,tag=le.ckeeper,x=%.1f,y=%.1f,z=%.1f,distance=..0.6] unless entity @a[gamemode=!spectator,x=%.1f,y=%.1f,z=%.1f,distance=..12] at @e[type=minecraft:villager,tag=le.ckeeper,limit=1] unless entity @a[gamemode=!spectator,distance=..12] run function last_ember:cemetery/gen/keeper_%s" % (sel, x, y, z, x, y, z, x, y, z, k))
        L.append("execute if score %s if loaded %d %d %d unless entity @e[type=minecraft:villager,tag=le.ckeeper] run function last_ember:cemetery/gen/keeper_%s" % (sel, x, y, z, k))
    for k, (x, y, z, yaw) in DG.items():
        sel = "#kp le.cem matches 0..1" if k == "home" else "#kp le.cem matches 2"
        w("dog_%s" % k, [hdr + "the keeper's dog: %s" % k, "kill @e[type=minecraft:wolf,tag=le.cdog]",
                         'summon minecraft:wolf %.1f %.1f %.1f {NoAI:1b,Invulnerable:1b,PersistenceRequired:1b,Silent:1b,Sitting:1b,Rotation:[%.1ff,0f],Tags:["le.npc","le.keep","le.noelite","le.cdog"]}' % (x, y, z, yaw)])
        L.append("execute if score %s if loaded %d %d %d unless entity @e[type=minecraft:wolf,tag=le.cdog,x=%.1f,y=%.1f,z=%.1f,distance=..0.6] run function last_ember:cemetery/gen/dog_%s" % (sel, x, y, z, x, y, z, k))
    L.append("execute as @e[type=minecraft:villager,tag=le.ckeeper] run data modify entity @s Health set value 20.0f")
    w("npcs", L)
    w("boxes", [hdr + "every second: the click boxes of the spyglass and the crypt door, the decor stands (once)",
                "execute if loaded %d %d %d unless entity @e[type=minecraft:interaction,tag=le.cspy] run summon minecraft:interaction %.1f %d %.1f {Tags:[\"le.cspy\"],width:0.7f,height:0.9f,response:1b}" % (sp[0], sp[1], sp[2], sp[0] + 0.5, sp[1], sp[2] + 0.5),
                "execute if loaded %d %d %d unless entity @e[type=minecraft:item_display,tag=le.cspyd] run summon minecraft:item_display %.1f %.2f %.1f {Tags:[\"le.cspyd\"],item:{id:\"minecraft:spyglass\",count:1},transformation:{left_rotation:[0.38f,0f,0f,0.92f],right_rotation:[0f,0f,0f,1f],translation:[0f,0f,0f],scale:[0.8f,0.8f,0.8f]},Rotation:[-90f,0f]}" % (sp[0], sp[1], sp[2], sp[0] + 0.5, sp[1] + 0.3, sp[2] + 0.5),
                "execute if loaded %d %d %d unless entity @e[type=minecraft:interaction,tag=le.cdoor] run summon minecraft:interaction %.1f %d %.1f {Tags:[\"le.cdoor\"],width:1.1f,height:2.1f,response:1b}" % (dr[0], dr[1], dr[2], dr[0] + 0.5, dr[1], dr[2] + 0.6),
                "execute if loaded %d %d %d unless entity @e[type=minecraft:armor_stand,tag=le.cstand] run function last_ember:cemetery/gen/stands" % tuple(lo["scarecrow"])])
    # the decor stands: rusty armour on old graves (brown leather, cannot be taken), the scarecrow of the garden
    S = [hdr + "the decor stands: rusty armour on 8 old graves, the scarecrow (summoned once; DisabledSlots after the armour)"]
    browns = (6704179, 5126182, 7031360, 4538147)
    for k, (x, y, z) in enumerate(meta["stands"]):
        c1 = browns[k % 4]
        eq = "{head:{id:\"minecraft:leather_helmet\",count:1,components:{\"minecraft:dyed_color\":%d,\"minecraft:custom_data\":{le_decor:1b}}},chest:{id:\"minecraft:leather_chestplate\",count:1,components:{\"minecraft:dyed_color\":%d,\"minecraft:custom_data\":{le_decor:1b}}},legs:{id:\"minecraft:leather_leggings\",count:1,components:{\"minecraft:dyed_color\":%d,\"minecraft:custom_data\":{le_decor:1b}}}}" % (c1, browns[(k + 1) % 4], c1)
        S.append('summon minecraft:armor_stand %d.5 %d %d.5 {Invulnerable:1b,ShowArms:1b,NoBasePlate:1b,Rotation:[%df,0f],Pose:{Head:[%df,0f,0f],RightArm:[%df,0f,0f]},Tags:["le.cstand","le.cdecor"],equipment:%s}' % (x, y, z, (k * 47) % 360, 10 + k * 3 % 20, -20 - k * 7 % 30, eq))
    x, y, z = lo["scarecrow"]
    S.append('summon minecraft:armor_stand %d.5 %d %d.5 {Invulnerable:1b,ShowArms:1b,NoBasePlate:1b,Rotation:[90f,0f],Pose:{RightArm:[0f,0f,-90f],LeftArm:[0f,0f,90f]},Tags:["le.cstand","le.cscare"],equipment:{head:{id:"minecraft:carved_pumpkin",count:1},chest:{id:"minecraft:leather_chestplate",count:1,components:{"minecraft:dyed_color":6704179}},legs:{id:"minecraft:leather_leggings",count:1,components:{"minecraft:dyed_color":4538147}}}}' % (x, y, z))
    S.append("execute as @e[type=minecraft:armor_stand,tag=le.cstand] run data merge entity @s {DisabledSlots:4144959}")
    w("stands", S)
    # ------------------------------------------------------------------ the spyglass: soul lights over the right graves and Thane (for @s only)
    L = [hdr + "every 10 ticks as a player who looked through the spyglass at night: columns of soul lights over the unopened right graves and Thane's"]
    for g in gv:
        if g["kind"] not in ("right", "thane"): continue
        for dy in (1.5, 2.5, 3.5, 4.5):
            L.append("execute if score #g%d le.cem matches 0 run particle minecraft:soul_fire_flame %d.5 %.1f %d.5 0.08 0.3 0.08 0.0 5 force @s" % (g["n"], g["x"], g["y"] + dy, g["z"]))
        L.append("execute if score #g%d le.cem matches 0 run particle minecraft:end_rod %d.5 %.1f %d.5 0.05 0.9 0.05 0.0 2 force @s" % (g["n"], g["x"], g["y"] + 3.0, g["z"]))
    w("spy", L)
    # ------------------------------------------------------------------ the crypt: the door, the Magister, the seal, the chest, the exit
    d0 = "minecraft:iron_door[facing=north,half=%s,hinge=left,open=%s,powered=false]"
    w("door_set", [hdr + "the crypt door as #door says (1 open for good)",
                   "execute if score #door le.cem matches 1 unless block %d %d %d minecraft:iron_door[open=true] run setblock %d %d %d %s" % (dr[0], dr[1], dr[2], dr[0], dr[1], dr[2], d0 % ("lower", "true")),
                   "execute if score #door le.cem matches 1 unless block %d %d %d minecraft:iron_door[open=true] run setblock %d %d %d %s" % (dr[0], dr[1] + 1, dr[2], dr[0], dr[1] + 1, dr[2], d0 % ("upper", "true")),
                   "execute if score #door le.cem matches 0 unless block %d %d %d minecraft:iron_door[open=false] run setblock %d %d %d %s" % (dr[0], dr[1], dr[2], dr[0], dr[1], dr[2], d0 % ("lower", "false")),
                   "execute if score #door le.cem matches 0 unless block %d %d %d minecraft:iron_door[open=false] run setblock %d %d %d %s" % (dr[0], dr[1] + 1, dr[2], dr[0], dr[1] + 1, dr[2], d0 % ("upper", "false"))])
    lid = cr["lid"]; hol = cr["hollow"]
    lidb = lambda x, z: "minecraft:chiseled_polished_blackstone" if (x + z) % 2 == 0 else "minecraft:polished_blackstone_bricks"
    w("lid_closed", [hdr + "the sarcophagus closed"] + ["setblock %d %d %d %s" % (x, y, z, lidb(x, z)) for (x, y, z) in lid] +
      ["setblock %d %d %d minecraft:air" % (x + 3, y, z) for (x, y, z) in lid if x == max(l[0] for l in lid)])
    w("lid_open", [hdr + "the lid pushed aside (askew to the east): the hollow is open"] + ["setblock %d %d %d minecraft:air" % (x, y, z) for (x, y, z) in lid] +
      ["setblock %d %d %d %s" % (x + 2, y, z, lidb(x, z)) for (x, y, z) in lid if x >= min(l[0] for l in lid) + 1] +
      ["setblock %d %d %d %s" % (max(l[0] for l in lid) + 3, lid[0][1] - 1, z, "minecraft:polished_blackstone_slab[type=bottom,waterlogged=false]") for z in sorted(set(l[2] for l in lid))[:2]])
    c2 = cr["chest2"]
