def comp_json(stack):
    """the components of a give-syntax stack as an NBT compound for summon (keys quoted, values as they are)"""
    inner = stack[stack.index("[") + 1:-1]
    parts = []; depth = 0; cur = ""
    for ch in inner:
        if ch in "{[": depth += 1
        if ch in "}]": depth -= 1
        if ch == "," and depth == 0: parts.append(cur); cur = ""
        else: cur += ch
    if cur: parts.append(cur)
    out = []
    for p in parts:
        if p.startswith("!"): continue
        k, v = p.split("=", 1)
        out.append('"%s":%s' % (k, v))
    return "{" + ",".join(out) + "}"
